from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, arr):
        # Template Method - skeleton is fixed
        n = len(arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(arr[j], arr[j + 1]):
                    self.swap(arr, j, j + 1)
        return arr

    @abstractmethod
    def compare(self, a, b):
        """return True if a should be swapped with b"""
        pass

    @abstractmethod
    def swap(self, arr, i, j):
        pass


class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]


class SelectionSort(SortAlgorithm):
    def sort(self, arr):
        # Selection sort has its own skeleton but reuses primitives
        n = len(arr)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(arr[j], arr[min_idx]):
                    min_idx = j
            if min_idx != i:
                self.swap(arr, i, min_idx)
        return arr

    def compare(self, a, b):
        return a < b

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]


